import*as THREE from'three';import{Button,Component,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import{grove,usb}from'./connectors.js';import{addStickers}from'./stickers.js';import data from'./geometry-data.js';const tau=Math.PI*2;
function solid(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:48}),m,p,n);}
function ring(parent,outer,inner,depth,pos,m,n){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);const h=new THREE.Path();h.absarc(0,0,inner,0,tau,false);s.holes.push(h);return solid(parent,s,depth,pos,m,n);}
function board(host){const s=new THREE.Shape(),x=9.6,r=3.8,row=-12,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);s.moveTo(-5.5,-22.4);s.lineTo(-8,-22.4);s.lineTo(-x,-20.8);s.lineTo(-x,row-dy);s.absarc(-8,row,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,16.4);s.lineTo(-8.3,17.8);s.lineTo(8.3,17.8);s.lineTo(x,16.4);s.lineTo(x,row+dy);s.absarc(8,row,r,a,tau-a,false);s.lineTo(x,-20.8);s.lineTo(8,-22.4);s.lineTo(5.5,-22.4);s.lineTo(5.5,-17.3);s.lineTo(-5.5,-17.3);s.closePath();for(const[cx,cy,radius]of[[0,row,2.8],...spec.download.holes.map(([x,y])=>[x,y,.5])]){const h=new THREE.Path();h.absarc(cx,cy,radius,0,tau,false);s.holes.push(h);}const green=materials.plastic(0x275e43,{roughness:.9}),metal=materials.metal(0xb3b8a9,{roughness:.47}),gold=materials.metal(0xbca260,{roughness:.5}),dark=materials.plastic(0x212921,{roughness:.86}),ceramic=materials.plastic(0xb4a37b,{roughness:.87}),pcb=solid(host.body,s,.8,[0,0,-1.6],green,'Gateway H2 shaped carrier PCB with true retaining and six unpopulated download through-holes');pcb.userData={role:'physical-pcb',inferred:true};const downloadPads=[],downloadSleeves=[];for(const[x,y]of spec.download.holes){downloadSleeves.push(ring(host.body,.5,.42,.8,[x,y,-1.6],metal,'Gateway H2 real plated download-hole barrel'));downloadPads.push(ring(host.body,.8,.42,.06,[x,y,-.8],metal,'Gateway H2 real annular unpopulated download land'));}
 const module=slab(host.body,13.2,16.6,.8,.04,[0,11.5,-.8],materials.plastic(0x18261c,{roughness:.87}),[],0);module.name='Gateway H2 ESP32-H2-MINI-1-N2 actual13.2×16.6mm fixed module PCB';const shield=slab(host.body,11.95,9.95,1.6,.16,[0,8.795,0],materials.metal(0xbdc1b7,{roughness:.62}),[],0);shield.name='Gateway H2 actual fixed ESP32-H2-MINI-1 shield envelope';const pads=[];for(const sign of[-1,1])for(let n=0;n<12;n++){pads.push(mesh(host.body,new THREE.BoxGeometry(.4,.8,.06),gold,[(n-5.5)*.8,8.8+sign*5.1,-.83],'Gateway H2 module actual underside perimeter land'));pads.push(mesh(host.body,new THREE.BoxGeometry(.8,.4,.06),gold,[sign*5.6,8.8+(n-5.5)*.8,-.83],'Gateway H2 module actual underside perimeter land'));}for(const x of[-5.6,5.6])for(const y of[3.7,13.9])pads.push(mesh(host.body,new THREE.BoxGeometry(.7,.7,.06),gold,[x,y,-.83],'Gateway H2 module actual corner ground land'));const thermalPads=[];for(const x of[-1.975,0,1.975])for(const y of[-1.975,0,1.975])thermalPads.push(mesh(host.body,new THREE.BoxGeometry(1.45,1.45,.06),gold,[x,8.8+y,-.83],'Gateway H2 module fixed underside thermal ground land'));
 const antenna=new THREE.Group();antenna.name='Gateway H2 fixed module-integrated planar PCB meander antenna';host.body.add(antenna);const route=[[-5.95,14.6],[-5.95,19.05],[-3.6,19.05],[-3.6,15.7],[-1.35,15.7],[-1.35,19.05],[1.05,19.05],[1.05,15.7],[3.4,15.7],[3.4,19.05],[5.8,19.05],[5.8,14.6]],antennaTracks=[];for(let i=1;i<route.length;i++){const[a,b]=[route[i-1],route[i]],dx=b[0]-a[0],dy=b[1]-a[1];antennaTracks.push(mesh(antenna,new THREE.BoxGeometry(Math.abs(dx)||.45,Math.abs(dy)||.45,.035),materials.metal(0x222b22,{roughness:.75}),[(a[0]+b[0])/2,(a[1]+b[1])/2,.0175],'Gateway H2 fixed non-emissive meander copper envelope'));}antenna.userData={role:'fixed-integrated-antenna',source:'Exact module datasheet p36/own naked-board photo',traceInstallationInferred:true};
 const regulator=slab(host.body,2.9,1.6,1.1,.08,[-1.2,-8,-.8],dark,[],.01);regulator.name='Gateway H2 U1 fixed BL8075CB5TR33 five-terminal regulator';const regulatorLeads=[];for(const[dx,dy]of[[-.95,-1],[0,-1],[.95,-1],[-.95,1],[.95,1]])regulatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.4,.65,.17),metal,[-1.2+dx,-8+dy,-.715],'Gateway H2 U1 physical solder terminal'));
 const crystal=slab(host.body,3.2,1.5,.75,.2,[-1.6,-4.8,-.8],metal,[],.015);crystal.name='Gateway H2 Y1 fixed32.768kHz metal crystal can envelope';const fuse=slab(host.body,2.5,1.3,.8,.08,[-6.9,-20.6,-.8],dark,[],.01);fuse.name='Gateway H2 F1 fixed protection fuse package';const diode=slab(host.body,2.1,1.25,.95,.07,[2,-8.4,-.8],dark,[],.01);diode.name='Gateway H2 D8 fixed B5819W diode package';const esd=[];for(const[x,y]of[[2,-1.8],[2,-4],[-3.4,-8.4],[6.9,-20.8],[7.8,-18.4],[5.6,-19],[-7.6,-8.4]]){const q=slab(host.body,.9,.6,.45,.04,[x,y,-.8],dark,[],.005);q.name='Gateway H2 fixed ESD/protection diode envelope';esd.push(q);}const passives=[];for(const[n,x,y,w,h]of[['C1',-8.3,11.2,1.6,.8],['C2',-8.3,8.7,1.6,.8],['C3',-8.3,6.2,1.2,.7],['C4',-8.1,1.6,1.2,.7],['C5',-4.2,-7.9,1.6,.8],['C6',-1.5,-2.8,1.2,.7],['C7',-1.5,-6.3,1.2,.7],['C8',-4.2,-1.5,1.6,.8],['C9',-7.5,-.6,1.2,.7],['C10',.3,-8.6,.8,1.3],['C11',8.1,-21,1.2,.7],['C12',-4.6,-20,1.6,.8],['R1',-8.1,3.8,1.2,.7],['R2',-7.8,-2.6,1.2,.7],['R3',-3.2,-2.3,1.2,.7],['R4 USB CC',2,-6.2,.7,1.2],['R5 USB CC',.7,-6.8,.7,1.2],['R7',-3,-6.8,1.2,.7]]){const q=slab(host.body,w,h,.5,.04,[x,y,-.8],n.startsWith('C')?ceramic:dark,[],.005);q.name='Gateway H2 fixed '+n+' passive package';passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.17,h,.12),metal,[x+sign*(w/2-.07),y,-.74],'Gateway H2 fixed passive solder end');}return{pcb,downloadPads,downloadSleeves,module,shield,pads,thermalPads,antenna,antennaTracks,regulator,regulatorLeads,crystal,fuse,diode,esd,passives};}
function boot(host,service){const metal=materials.metal(0xb6bcaf,{roughness:.5}),dark=materials.plastic(0x171c18,{roughness:.85}),base=slab(host.body,4.2,3.4,.6,.16,[-6.4,-4.8,-.8],metal,[],.02);base.name='Gateway H2 S1 actual PTS820 metal switch base';const cap=new THREE.Group();cap.name='Gateway H2 real black momentary Boot cap';mesh(cap,new THREE.CylinderGeometry(.85,.85,.4,40).rotateX(Math.PI/2),dark,[0,0,0],'Gateway H2 Boot physical round actuator');let button=null;if(service)button=host.add(new Button({id:'boot',label:'Bare-PCB Boot · S1 GPIO9 input intent',position:spec.boot.position,mesh:cap,travel:.15,axis:[0,0,-1],longPressMs:0,meta:{role:'visual-control',serviceOnly:true,surfaceFace:'front',travelSource:'0.15mm appearance reconstruction;own U195_04 and download GIF prove actual momentary button and bare-board access,not rated travel',scope:'Real cap press/release/cancel and input intent only;no boot mode,reset,programming,GPIO,firmware,USB,wireless,network,power or electrical behavior'}}));else{cap.position.fromArray(spec.boot.position);host.body.add(cap);}const terminals=[];for(const sign of[-1,1])for(const dy of[-1,1])terminals.push(mesh(host.body,new THREE.BoxGeometry(.55,.55,.15),metal,[-6.4+sign*2.1,-4.8+dy,-.725],'Gateway H2 Boot fixed switch solder terminal'));return{base,cap,button,terminals};}
export function buildGatewayH2(host,{shell=host.options.shell??true}={}){if(typeof shell!=='boolean')throw new TypeError('shell must be true or false');const parts=shell?addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.8})}):{},pcb=board(host),input=grove(host),serviceUsb=usb(host,{interactive:!shell}),key=boot(host,!shell),download=!shell?host.add(new Component({id:'download',label:'Bare-PCB six unpopulated plated download-hole anchor',position:spec.download.position,meta:{role:'visual-anchor',serviceOnly:true,source:'Own U195_04 bare-board photo and J1 DownloadSocket schematic;no populated plastic header seen',holePositionsMm:spec.download.holes,pins:spec.download.labels,scope:'Passive location/labels only for six real bare plated holes;no fabricated plastic socket,attachment family,flashing,UART,GPIO,boot or electrical behavior'}})):null;let fixing=null,labels={};if(shell){fixing=screw(host.body,[0,-12,-3.98],'back',1.25);fixing.name='Gateway H2 fixed rear shell retaining screw';mesh(host.body,new THREE.CylinderGeometry(.6,.6,5.8,24).rotateX(Math.PI/2),materials.metal(0xa3a89c),[0,-12,-.45],'Gateway H2 fixed concealed shell screw shank');const film=materials.plastic(0xdfdfd9,{roughness:.87});for(const face of['front','back']){const p=slab(host.body,...spec.labels[face].size,.08,.08,spec.labels[face].position,film,[],.005);p.name='Gateway H2 real '+face+' adhesive film on native label support';p.userData={role:'physical-label-substrate',face};labels[face]=p;}}host.gatewayH2Assembly={shell,parts,pcb,input,usb:serviceUsb,boot:key,download,fixing,labels};host.unitStickers=shell?addStickers(host):[];}
